    // resolved once per customer in the response.
    @Test
    void orderCountsForAResponseComeFromOneQuery() {
        Customer ada = new Customer(1L, "Ada", "ada@example.com", "GOLD");
        Customer grace = new Customer(2L, "Grace", "grace@example.com", "SILVER");
        given(orders.findBy(any(), any(), any())).willReturn(window(
                new Order(1L, 3_000, AT), new Order(2L, 4_000, AT), new Order(1L, 5_000, AT)));
        given(customers.findAllById(any())).willReturn(List.of(ada, grace));
        given(orders.countByCustomerIdIn(any())).willReturn(List.of(
                new CustomerOrderCount(1L, 7), new CustomerOrderCount(2L, 2)));

        graphQlTester.document("{ orders { edges { node { customer { name orderCount } } } } }")
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class)
                .isEqualTo(7)
                .path("orders.edges[1].node.customer.orderCount").entity(Integer.class)
                .isEqualTo(2)
                .path("orders.edges[2].node.customer.orderCount").entity(Integer.class)
                .isEqualTo(7);

        ArgumentCaptor<Collection<Long>> asked = ArgumentCaptor.captor();
        verify(orders, times(1)).countByCustomerIdIn(asked.capture());
        assertThat(asked.getValue()).containsExactlyInAnyOrder(1L, 2L);
    }

