    void aCustomerWithNoOrdersCountsZero() {
        given(orders.findBy(any(), any(), any())).willReturn(window(new Order(1L, 3_000, AT)));
        given(customers.findAllById(any())).willReturn(
                List.of(new Customer(1L, "Ada", "ada@example.com", "GOLD")));
        given(orders.countByCustomerIdIn(any())).willReturn(List.of());

        graphQlTester.document("{ orders { edges { node { customer { orderCount } } } } }")
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class)
                .isEqualTo(0);
    }

    @Test
    void customerOrdersPagesThroughOneCustomersOrders() {
        given(customers.existsById(1L)).willReturn(true);
        given(orders.findByCustomerId(eq(1L), any(), any(), any())).willReturn(window(
                new Order(1L, 3_000, AT), new Order(1L, 4_000, AT)));

        graphQlTester.document("""
                        { customerOrders(customerId: 1, first: 2) {
                            edges { cursor node { amount } }
                            pageInfo { hasNextPage }
                        } }""")
                .execute()
                .path("customerOrders.edges").hasSize(2)
                .path("customerOrders.edges[0].node.amount").entity(Integer.class)
                .isEqualTo(3000)
                .path("customerOrders.edges[1].node.amount").entity(Integer.class)
                .isEqualTo(4000)
                .path("customerOrders.edges[0].cursor").entity(String.class).satisfies(
                        cursor -> assertThat(cursor).isNotEmpty())
                .path("customerOrders.pageInfo.hasNextPage").entity(Boolean.class)
                .isEqualTo(false);

        verify(orders).findByCustomerId(1L, ScrollPosition.keyset(), Limit.of(2), Sort.by("id"));
    }

    @Test
    void customerOrdersDefaultsToTenPerPage() {
        given(customers.existsById(1L)).willReturn(true);
        given(orders.findByCustomerId(eq(1L), any(), any(), any()))
                .willReturn(window(new Order(1L, 3_000, AT)));

        graphQlTester.document("{ customerOrders(customerId: 1) { edges { node { amount } } } }")
                .execute()
                .path("customerOrders.edges").hasSize(1);

        verify(orders).findByCustomerId(1L, ScrollPosition.keyset(), Limit.of(10), Sort.by("id"));
    }

    // The cursor from one page is the position the next page starts after.
    @Test
    void customerOrdersFollowsTheCursor() {
        given(customers.existsById(1L)).willReturn(true);
        given(orders.findByCustomerId(eq(1L), any(), any(), any()))
                .willReturn(window(new Order(1L, 3_000, AT)));

        String cursor = graphQlTester
                .document("{ customerOrders(customerId: 1, first: 1) { edges { cursor } } }")
                .execute()
                .path("customerOrders.edges[0].cursor").entity(String.class).get();

        graphQlTester.document(
                        "query Next($after: String) { customerOrders(customerId: 1, first: 1,"
                                + " after: $after) { edges { node { amount } } } }")
                .variable("after", cursor)
                .execute()
                .path("customerOrders.edges").hasSize(1);

        ArgumentCaptor<ScrollPosition> position = ArgumentCaptor.captor();
        verify(orders, times(2)).findByCustomerId(eq(1L), position.capture(), any(), any());
        assertThat(position.getAllValues().get(1)).isNotEqualTo(ScrollPosition.keyset());
    }

    @Test
    void aMissingCustomerIsNotFound() {
        given(customers.existsById(42L)).willReturn(false);

        graphQlTester.document("{ customerOrders(customerId: 42) { edges { node { id } } } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND
                        && error.getMessage().contains("42"));
    }

    private static Window<Order> window(Order... found) {
        return Window.from(List.of(found), ScrollPosition::offset);
    }
